// One row per hotel and check-in date: lowest price and site, official site price, and the main booking sites' prices.
const today = new Date().toISOString().slice(0, 10);
const watched = ['Booking.com', 'Expedia', 'Hotels.com', 'Agoda', 'Trip.com'];
return $input.all()
  .map((i) => i.json)
  .filter((h) => h.found !== false)
  .map((h) => {
    // Site names vary a little ("Expedia.com"): matched on how they start.
    const price = (name) => (h.sites ?? []).find((s) => String(s.site ?? '').toLowerCase().startsWith(name.toLowerCase()))?.price ?? null;
    const row = {
      checkedOn: today,
      hotel: h.name,
      checkIn: h.checkIn,
      checkOut: h.checkOut,
      currency: h.currency,
      lowestPrice: h.lowestPrice,
      lowestPriceSite: h.lowestPriceSite,
      officialSitePrice: h.officialSitePrice,
      highestPrice: h.highestPrice,
      sitesCount: h.sitesCount,
    };
    for (const name of watched) row[name] = price(name);
    return { json: row };
  });
